window.docContents[41].resolve({"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Left-and-right-modules-over-commutative-rings/#Chapter2___Remark2___3___2":{"contents":"Remark 2.3.2. Let M be a left module over a commutative ring A. Then one can regard M as a right A-module, with ma := am. Similarly, any right A-module can be regarded as a left A-module. For this reason, for commutative rings one does not distinguish between left and right A-modules and just calls them A-modules.\n\n\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.3. Representations\u0009Left and right modules over commutative rings","header":"Left and right modules over commutative rings","id":"/2___-Basic-notions-of-representation-theory/2___3___-Representations/Left-and-right-modules-over-commutative-rings/#Chapter2___Remark2___3___2"},"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Generators-and-relations-for-the-path-algebra/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___8___-Quivers--Generators-and-relations-for-the-path-algebra--Generators-and-relations-for-the-path-algebra--Formalization--Primary-declarations":{"contents":"The opposite vertex and arrow elements generate the entire displayed algebra.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter2/Problem2.8.6; role=primary]\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.8. Quivers\u0009Generators and relations for the path algebra\u0009Generators and relations for the path algebra\u0009Formalization","header":"Primary declarations","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Generators-and-relations-for-the-path-algebra/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___8___-Quivers--Generators-and-relations-for-the-path-algebra--Generators-and-relations-for-the-path-algebra--Formalization--Primary-declarations"},"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___9___-Lie-algebras--Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras":{"contents":"\n\n","context":"Introduction to Representation Theory\u00092. Basic notions of representation theory\u00092.9. Lie algebras","header":"Examples of Lie algebras (continued): Lie subalgebras","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras/#Introduction-to-Representation-Theory--2___-Basic-notions-of-representation-theory--2___9___-Lie-algebras--Examples-of-Lie-algebras-_LPAR_continued_RPAR____-Lie-subalgebras"},"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Classification-of-subrepresentations-in-semisimple-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___1___-Subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations--Formalization--Primary-declarations":{"contents":"A submodule of a direct sum of pairwise inequivalent simple types is equivalent to a direct sum with bounded multiplicities.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter3/Discussion_proof_of_Theorem3.3.1; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter3/Proposition3.1.4; role=primary]\n\nEvery nontrivial finite-dimensional module contains a subtype that is simple as a module.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter2/Problem2.3.15; role=primary]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter3/Proposition3.1.4/Derived3; role=primary]\n\n","context":"Introduction to Representation Theory\u00093. General results of representation theory\u00093.1. Subrepresentations in semisimple representations\u0009Classification of subrepresentations in semisimple representations\u0009Classification of subrepresentations in semisimple representations\u0009Formalization","header":"Primary declarations","id":"/3___-General-results-of-representation-theory/3___1___-Subrepresentations-in-semisimple-representations/Classification-of-subrepresentations-in-semisimple-representations/#Introduction-to-Representation-Theory--3___-General-results-of-representation-theory--3___1___-Subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations--Classification-of-subrepresentations-in-semisimple-representations--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___--a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function--a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function--Formalization--Primary-declarations":{"contents":"For each partition, there is a function-like scalar-valued object such that placing any group-algebra element between the two displayed idempotent elements gives its scalar value times a third displayed element.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Introduction_5.13; role=supporting]* Etingof et al., Introduction to Representation Theory [book-ref=Chapter5/Lemma5.13.1; role=primary]\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.13. Proof of the classification theorem for representations of $S_n$\u0009a_lambda x b_lambda = l_lambda(x) c_lambda where l_lambda is a linear function\u0009a_lambda x b_lambda = l_lambda(x) c_lambda where l_lambda is a linear function\u0009Formalization","header":"Primary declarations","id":"/5___-Representations-of-finite-groups___-Further-results/5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___/a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___13___-Proof-of-the-classification-theorem-for-representations-of-___S_n___--a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function--a_lambda-x-b_lambda-___-l_lambda_LPAR_x_RPAR_-c_lambda-where-l_lambda-is-a-linear-function--Formalization--Primary-declarations"},"/5___-Representations-of-finite-groups___-Further-results/5___3___-Frobenius-divisibility/The-numbers-lambda_i-are-algebraic-integers/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___3___-Frobenius-divisibility--The-numbers-lambda_i-are-algebraic-integers":{"contents":"\n\n","context":"Introduction to Representation Theory\u00095. Representations of finite groups: Further results\u00095.3. Frobenius divisibility","header":"The numbers lambda_i are algebraic integers","id":"/5___-Representations-of-finite-groups___-Further-results/5___3___-Frobenius-divisibility/The-numbers-lambda_i-are-algebraic-integers/#Introduction-to-Representation-Theory--5___-Representations-of-finite-groups___-Further-results--5___3___-Frobenius-divisibility--The-numbers-lambda_i-are-algebraic-integers"},"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/Remark-6___2___1___-Notation-for-dimension-diagrams/#Chapter6___Remark6___2___1":{"contents":"Remark 6.2.1. By an object of the type 1 \\xrightarrow{} 0 we mean a map from a 1-dimensional vector space to the zero space. Similarly, an object of the type 0 \\xrightarrow{} 1 is a map from the zero space into a 1-dimensional space. The object 1 \\xrightarrow{} 1 means an isomorphism from a 1-dimensional to another 1-dimensional space. The numbers in such diagrams always mean the dimension of the attached spaces and the maps are the canonical maps (unless specified otherwise).\n\n\n","context":"Introduction to Representation Theory\u00096. Quiver representations\u00096.2. Indecomposable representations of the quivers $A_1$, $A_2$, $A_3$\u0009Remark 6.2.1: Notation for dimension diagrams","header":"Remark 6.2.1: Notation for dimension diagrams","id":"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/Remark-6___2___1___-Notation-for-dimension-diagrams/#Chapter6___Remark6___2___1"},"/7___-Introduction-to-categories/7___9___-Exact-functors/Additive-and-k-linear-functor/#Chapter7___Definition7___9___1":{"contents":"Definition 7.9.1. A functor F between two abelian categories is additive if it induces homomorphisms on Hom groups. Also, for k-linear categories one says that F is k-linear if it induces k-linear maps between Hom spaces.\n\n\n\n","context":"Introduction to Representation Theory\u00097. Introduction to categories\u00097.9. Exact functors\u0009Additive and k-linear functor","header":"Additive and k-linear functor","id":"/7___-Introduction-to-categories/7___9___-Exact-functors/Additive-and-k-linear-functor/#Chapter7___Definition7___9___1"},"/9___-Structure-of-finite-dimensional-algebras/9___1___-Lifting-of-idempotents/Lifting-of-idempotents-from-quotient-by-nilpotent-ideal/#Chapter9___Proposition9___1___1___formalization":{"contents":"\n\n\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.1. Lifting of idempotents\u0009Lifting of idempotents from quotient by nilpotent ideal\u0009Lifting of idempotents from quotient by nilpotent ideal","header":"Formalization","id":"/9___-Structure-of-finite-dimensional-algebras/9___1___-Lifting-of-idempotents/Lifting-of-idempotents-from-quotient-by-nilpotent-ideal/#Chapter9___Proposition9___1___1___formalization"},"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-category/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Finite-abelian-category--Finite-abelian-category--Formalization--Primary-declarations":{"contents":"A category whose subobject orders are finite-dimensional.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Definition9.6.1; role=primary]An auxiliary type associated to the category.* Etingof et al., Introduction to Representation Theory [book-ref=Chapter9/Definition9.6.1; role=supporting]\n\n","context":"Introduction to Representation Theory\u00099. Structure of finite dimensional algebras\u00099.6. Finite abelian categories\u0009Finite abelian category\u0009Finite abelian category\u0009Formalization","header":"Primary declarations","id":"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Finite-abelian-category/#Introduction-to-Representation-Theory--9___-Structure-of-finite-dimensional-algebras--9___6___-Finite-abelian-categories--Finite-abelian-category--Finite-abelian-category--Formalization--Primary-declarations"}});